ALTER TABLE public.profiles ADD COLUMN date_of_birth date, ADD COLUMN postal_code text NOT NULL DEFAULT '', ADD COLUMN notification_preferences jsonb NOT NULL DEFAULT '{"shipment":true,"account":true,"support":true}';
ALTER TABLE public.service_requests DROP CONSTRAINT service_requests_kind_check;
ALTER TABLE public.service_requests ADD CONSTRAINT service_requests_kind_check CHECK (kind IN ('contact','quote','booking','newsletter','support','phone_verification','deactivation'));
ALTER POLICY "Customers create booking requests" ON public.service_requests TO authenticated WITH CHECK (kind IN ('booking','support','phone_verification','deactivation') AND user_id=auth.uid() AND public.is_active_customer());
ALTER POLICY "Read own notifications" ON public.customer_notifications TO authenticated USING (user_id=auth.uid() AND public.is_active_customer()) WITH CHECK (user_id=auth.uid() AND public.is_active_customer());
CREATE POLICY "Customers read own support replies" ON public.support_replies FOR SELECT TO authenticated USING (public.is_active_customer() AND EXISTS (SELECT 1 FROM public.service_requests r WHERE r.id=support_replies.request_id AND r.user_id=auth.uid()));
CREATE TABLE public.customer_sessions(session_id text PRIMARY KEY,user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,first_seen timestamptz NOT NULL DEFAULT now(),last_seen timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.customer_sessions TO authenticated;
GRANT ALL ON public.customer_sessions TO service_role;
ALTER TABLE public.customer_sessions ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Own session history or master" ON public.customer_sessions FOR SELECT TO authenticated USING ((user_id=auth.uid() AND public.is_active_customer()) OR public.is_master_admin());
CREATE FUNCTION public.record_customer_session(p_session_id text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.is_active_customer() OR p_session_id IS DISTINCT FROM (auth.jwt()->>'session_id') THEN RAISE EXCEPTION 'Active verified session required'; END IF; INSERT INTO public.customer_sessions(session_id,user_id) VALUES(p_session_id,auth.uid()) ON CONFLICT(session_id) DO UPDATE SET last_seen=now() WHERE customer_sessions.user_id=auth.uid(); END $$;
CREATE FUNCTION public.update_customer_profile(p_details jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE dob date; BEGIN IF NOT public.is_active_customer() THEN RAISE EXCEPTION 'Active customer required'; END IF; IF length(coalesce(p_details->>'first_name','')) NOT BETWEEN 1 AND 80 OR length(coalesce(p_details->>'last_name',''))>80 OR length(coalesce(p_details->>'address',''))>300 OR length(coalesce(p_details->>'city',''))>100 OR length(coalesce(p_details->>'state',''))>100 OR length(coalesce(p_details->>'country',''))>100 OR length(coalesce(p_details->>'postal_code',''))>30 THEN RAISE EXCEPTION 'Invalid profile details'; END IF; dob=nullif(p_details->>'date_of_birth','')::date; IF dob>current_date THEN RAISE EXCEPTION 'Invalid date of birth'; END IF; UPDATE public.profiles SET first_name=trim(p_details->>'first_name'),last_name=coalesce(trim(p_details->>'last_name'),''),address=coalesce(trim(p_details->>'address'),''),city=coalesce(trim(p_details->>'city'),''),state=coalesce(trim(p_details->>'state'),''),country=coalesce(trim(p_details->>'country'),''),postal_code=coalesce(trim(p_details->>'postal_code'),''),date_of_birth=dob,updated_by=auth.uid() WHERE id=auth.uid(); END $$;
CREATE FUNCTION public.update_customer_avatar(p_path text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,storage AS $$ BEGIN IF NOT public.is_active_customer() THEN RAISE EXCEPTION 'Active customer required'; END IF; IF p_path<>'' AND (split_part(p_path,'/',1)<>auth.uid()::text OR NOT EXISTS(SELECT 1 FROM storage.objects WHERE bucket_id='customer-pictures' AND name=p_path)) THEN RAISE EXCEPTION 'Invalid picture'; END IF; UPDATE public.profiles SET avatar_path=p_path,updated_by=auth.uid() WHERE id=auth.uid(); END $$;
CREATE FUNCTION public.update_customer_preferences(p_preferences jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.is_active_customer() THEN RAISE EXCEPTION 'Active customer required'; END IF; IF jsonb_typeof(p_preferences->'shipment') IS DISTINCT FROM 'boolean' OR jsonb_typeof(p_preferences->'account') IS DISTINCT FROM 'boolean' OR jsonb_typeof(p_preferences->'support') IS DISTINCT FROM 'boolean' THEN RAISE EXCEPTION 'Invalid preferences'; END IF; UPDATE public.profiles SET notification_preferences=jsonb_build_object('shipment',p_preferences->'shipment','account',p_preferences->'account','support',p_preferences->'support'),updated_by=auth.uid() WHERE id=auth.uid(); END $$;
CREATE FUNCTION public.manage_customer_notification(p_id uuid,p_action text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.is_active_customer() THEN RAISE EXCEPTION 'Active customer required'; END IF; IF p_action='read' THEN UPDATE public.customer_notifications SET read_at=coalesce(read_at,now()) WHERE user_id=auth.uid() AND (p_id IS NULL OR id=p_id); ELSIF p_action='delete' AND p_id IS NOT NULL THEN DELETE FROM public.customer_notifications WHERE user_id=auth.uid() AND id=p_id AND read_at IS NOT NULL; ELSE RAISE EXCEPTION 'Invalid notification action'; END IF; END $$;
REVOKE ALL ON FUNCTION public.record_customer_session(text),public.update_customer_profile(jsonb),public.update_customer_avatar(text),public.update_customer_preferences(jsonb),public.manage_customer_notification(uuid,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.record_customer_session(text),public.update_customer_profile(jsonb),public.update_customer_avatar(text),public.update_customer_preferences(jsonb),public.manage_customer_notification(uuid,text) TO authenticated;
CREATE POLICY "Owner and master read customer pictures" ON storage.objects FOR SELECT TO authenticated USING (bucket_id='customer-pictures' AND ((split_part(name,'/',1)=auth.uid()::text AND public.is_active_customer()) OR public.is_master_admin()));
CREATE POLICY "Active customers upload own pictures" ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='customer-pictures' AND split_part(name,'/',1)=auth.uid()::text AND public.is_active_customer());
CREATE POLICY "Active customers remove own pictures" ON storage.objects FOR DELETE TO authenticated USING(bucket_id='customer-pictures' AND split_part(name,'/',1)=auth.uid()::text AND public.is_active_customer());
CREATE POLICY "Customers read assigned profile picture" ON storage.objects FOR SELECT TO authenticated USING(bucket_id='admin-documents' AND public.is_active_customer() AND EXISTS(SELECT 1 FROM public.profiles p WHERE p.id=auth.uid() AND p.avatar_path=storage.objects.name));
CREATE FUNCTION public.notify_customer_record() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE uid uuid; sid uuid; category text; title text; message text; BEGIN IF TG_TABLE_NAME='shipments' THEN uid=NEW.user_id;sid=NEW.id;category='shipment'; IF TG_OP='INSERT' THEN title='Shipment created';message='Your shipment '||NEW.tracking_id||' has been registered.'; ELSIF NEW.cancelled_at IS DISTINCT FROM OLD.cancelled_at AND NEW.cancelled_at IS NOT NULL THEN title='Shipment cancelled';message='Shipment '||NEW.tracking_id||' has been cancelled.'; ELSIF NEW.estimated_delivery IS DISTINCT FROM OLD.estimated_delivery OR NEW.destination IS DISTINCT FROM OLD.destination THEN title='Shipment details updated';message='The details for '||NEW.tracking_id||' have been updated.'; ELSE RETURN NEW; END IF; ELSIF TG_TABLE_NAME='shipment_events' THEN SELECT user_id,id INTO uid,sid FROM public.shipments WHERE id=NEW.shipment_id;category='shipment';title=NEW.status;message=NEW.location||CASE WHEN NEW.description<>'' THEN ' · '||NEW.description ELSE '' END; ELSIF TG_TABLE_NAME='profiles' THEN IF NEW.account_status IS NOT DISTINCT FROM OLD.account_status THEN RETURN NEW; END IF;uid=NEW.id;category='account';title='Account status updated';message='Your account is now '||NEW.account_status||'.'; END IF; IF uid IS NOT NULL THEN INSERT INTO public.customer_notifications(user_id,shipment_id,category,title,message,updated_by) VALUES(uid,sid,category,title,message,NEW.updated_by); END IF; RETURN NEW; END $$;
CREATE TRIGGER notify_customer_shipment AFTER INSERT OR UPDATE ON public.shipments FOR EACH ROW EXECUTE FUNCTION public.notify_customer_record();
CREATE TRIGGER notify_customer_tracking AFTER INSERT OR UPDATE ON public.shipment_events FOR EACH ROW EXECUTE FUNCTION public.notify_customer_record();
CREATE TRIGGER notify_customer_account AFTER UPDATE ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.notify_customer_record();